function validate([graph]) {
  if (!Array.isArray(graph) || graph.length < 3 || graph.length > 50) return 'graph needs 3 to 50 nodes.';
  const n = graph.length;
  for (let i = 0; i < n; i++) {
    const list = graph[i];
    if (!Array.isArray(list) || list.length < 1 || list.length >= n) return `Node ${i} needs 1 to ${n - 1} neighbours.`;
    if (list.some(j => !Number.isInteger(j) || j < 0 || j >= n || j === i)) return `Node ${i} lists an invalid neighbour.`;
    if (new Set(list).size !== list.length) return `Node ${i} lists a neighbour twice.`;
  }
  for (let i = 0; i < n; i++) {
    for (const j of graph[i]) if (!graph[j].includes(i)) return `Edge ${i}-${j} must appear in both lists.`;
  }
  const seen = new Set([2]);
  const stack = [2];
  while (stack.length > 0) {
    const node = stack.pop();
    const moves = graph[node].filter(next => next !== 0);
    if (moves.length === 0) return `The cat could get stuck on node ${node}.`;
    for (const next of moves) if (!seen.has(next)) { seen.add(next); stack.push(next); }
  }
  return null;
}

