function catMouseGame(graph) {
  const n = graph.length;
  const MOUSE_TURN = 0;
  const CAT_TURN = 1;
  const DRAW = 0;
  const MOUSE_WIN = 1;
  const CAT_WIN = 2;
  const offHole = graph.map(neighbours => neighbours.filter(next => next !== 0));
  const result = new Map();
  const movesLeft = new Map();
  const queue = [];
  for (let cat = 1; cat < n; cat++) {
    result.set(`0,${cat},${CAT_TURN}`, MOUSE_WIN);
    result.set(`${cat},${cat},${CAT_TURN}`, CAT_WIN);
    result.set(`${cat},${cat},${MOUSE_TURN}`, CAT_WIN);
    queue.push([0, cat, CAT_TURN, MOUSE_WIN], [cat, cat, CAT_TURN, CAT_WIN], [cat, cat, MOUSE_TURN, CAT_WIN]);
  }

  while (queue.length > 0) {
    const [mouse, cat, turn, outcome] = queue.shift();
    const prevTurn = 1 - turn;
    const movedFrom = prevTurn === MOUSE_TURN ? offHole[mouse] : offHole[cat];
    for (const prev of movedFrom) {
      const key = prevTurn === MOUSE_TURN ? `${prev},${cat},${prevTurn}` : `${mouse},${prev},${prevTurn}`;
      if (!result.has(key)) {
        const left = (movesLeft.get(key) ?? (prevTurn === MOUSE_TURN ? graph[prev] : offHole[prev]).length) - 1;
        movesLeft.set(key, left);
        if (left === 0 || outcome === (prevTurn === MOUSE_TURN ? MOUSE_WIN : CAT_WIN)) {
          result.set(key, outcome);
          queue.push(prevTurn === MOUSE_TURN ? [prev, cat, prevTurn, outcome] : [mouse, prev, prevTurn, outcome]);
        }
      }
    }
  }
  return result.get(`1,2,${MOUSE_TURN}`) ?? DRAW;
}

