function catMouseGame(graph) {
  // Repeat the minimax rules over every state until nothing changes; unsettled states are draws.
  const n = graph.length;
  const value = [0, 1].map(() => Array.from({ length: n }, () => new Array(n).fill(0)));
  for (let t = 0; t < 2; t++) {
    for (let c = 1; c < n; c++) {
      value[t][0][c] = 1;
      value[t][c][c] = 2;
    }
  }
  let changed = true;
  while (changed) {
    changed = false;
    for (let m = 1; m < n; m++) {
      for (let c = 1; c < n; c++) {
        if (m === c) continue;
        if (value[0][m][c] === 0) {
          const outs = graph[m].map(next => value[1][next][c]);
          const v = outs.includes(1) ? 1 : outs.every(o => o === 2) ? 2 : 0;
          if (v !== 0) { value[0][m][c] = v; changed = true; }
        }
        if (value[1][m][c] === 0) {
          const outs = graph[c].filter(next => next !== 0).map(next => value[0][m][next]);
          const v = outs.includes(2) ? 2 : outs.length > 0 && outs.every(o => o === 1) ? 1 : 0;
          if (v !== 0) { value[1][m][c] = v; changed = true; }
        }
      }
    }
  }
  return value[0][1][2];
}

