function generate(rand, size) {
  const large = size === 'large';
  for (;;) {
    const n = large ? 30 + Math.floor(rand() * 21) : 3 + Math.floor(rand() * 6);
    const ring = rand() < 0.4;
    const density = ring ? rand() * 0.12 : large ? 0.04 + rand() * 0.16 : 0.2 + rand() * 0.5;
    const holeDensity = ring ? 0.15 : density * rand() * (large ? 1 : 0.5);
    const adj = Array.from({ length: n }, () => new Set());
    const link = (a, b) => { adj[a].add(b); adj[b].add(a); };
    if (ring && n >= 4) {
      // A shuffled cycle through nodes 1..n-1 gives the mouse room to run, which is where draws come from.
      const order = Array.from({ length: n - 1 }, (_, i) => i + 1);
      for (let i = order.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [order[i], order[j]] = [order[j], order[i]];
      }
      for (let i = 0; i < order.length; i++) link(order[i], order[(i + 1) % order.length]);
    }
    for (let a = 0; a < n; a++) {
      for (let b = a + 1; b < n; b++) {
        if (rand() < (a === 0 ? holeDensity : density)) link(a, b);
      }
    }
    for (let a = 0; a < n; a++) {
      if (adj[a].size > 0) continue;
      let b = Math.floor(rand() * (n - 1));
      if (b >= a) b++;
      link(a, b);
    }
    const graph = adj.map(set => [...set].sort((x, y) => x - y));
    // The cat must always have a move: every node it can reach needs a neighbour other than the hole.
    const seen = new Set([2]);
    const stack = [2];
    let stuck = false;
    while (stack.length > 0 && !stuck) {
      const node = stack.pop();
      const moves = graph[node].filter(next => next !== 0);
      if (moves.length === 0) stuck = true;
      for (const next of moves) if (!seen.has(next)) { seen.add(next); stack.push(next); }
    }
    if (!stuck) return [graph];
  }
}
